use crate::model::Summary;
fn checksum(data:&[u8])->u8 {data.iter().fold(0u8,|sum,b|sum.wrapping_add(*b))}
pub fn run(data:&[u8],limit:i64)->Summary {
 let mut frames=Vec::new();
 let mut cursor=0;
 let mut error=0;
 while cursor<data.len() && error==0 {
  let start=cursor;
  let header=data[start];
  if header==255 {
   cursor+=1;
   continue;
  }
  let (length,payload_start)=if header==254 {
   if data.len()-start<3 {error=1;break;}
   let length=(data[start+1] as usize)|((data[start+2] as usize)<<8);
   (length,start+3)
  } else {
   (header as usize,start+1)
  };
  if length as i64>limit {error=3;break;}
  if data.len()-payload_start<length+1 {error=1;break;}
  let payload_end=payload_start+length;
  let payload=&data[payload_start..payload_end];
  if checksum(payload)!=data[payload_end] {error=2;break;}
  frames.push(payload.to_vec());
  cursor=payload_end+1;
 }
 Summary {frames,consumed:cursor as i64,error}
}

